node -e '
const fs=require("fs"),path=require("path"),yaml=require("yaml");
const exts=[".scl",".spec.md",".spec.yaml",".spec"];const codeSpec=/\.[a-z]+\.spec$/;
const files=[];(function walk(d){for(const e of fs.readdirSync(d,{withFileTypes:true})){if([".git",".opencode",".backup_spec_files"].includes(e.name))continue;const p=path.join(d,e.name);if(e.isDirectory())walk(p);else if(e.isFile()){const r=path.relative("specs",p);if(r.includes(".backup_spec_files"))continue;if(exts.some(x=>e.name.endsWith(x))||codeSpec.test(e.name))files.push(p);}}})("specs");
console.log("files:",files.length);
const ids=[];
for(const f of files){
  const content=fs.readFileSync(f,"utf-8");const lines=content.split("\n");
  let metadata={};
  for(let i=0;i<lines.length;i++){
    if(lines[i].includes("speclang-header")){
      const m=lines[i].match(/lines:\s*(\d+)/);const hl=m?parseInt(m[1],10):0;
      const yl=[];let j=i+1;const end=hl>0?Math.min(j+hl-1,lines.length):lines.length;
      for(let k=j;k<end;k++){if(lines[k].trim()==="---")break;yl.push(lines[k]);}
      if(yl.length>0){try{metadata=yaml.parse(yl.join("\n"))||{};}catch(e){const im=yl.join("\n").match(/id:\s*(@[^\s]+)/);if(im)metadata.id=im[1];}}
      break;
    }
  }
  ids.push({f,id:metadata.id??null});
}
const noId=ids.filter(x=>!x.id);console.log("no id:",noId.length);noId.slice(0,10).forEach(x=>console.log("  ",x.f));
const counts={};ids.forEach(x=>{if(x.id)counts[x.id]=(counts[x.id]||0)+1;});
const dups=Object.entries(counts).filter(([k,v])=>v>1);
console.log("unique ids:",Object.keys(counts).length,"dup ids:",dups.length,"excess:",dups.reduce((s,[k,v])=>s+v-1,0));
dups.forEach(([k,v])=>console.log("  dup",v,k));
' 2>&1 | head -40
